def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.176.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.175.0"' not in init:
        sys.exit("ABORT: not at v3.175.0.")
    for k in ("performance", "training"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("HR5", LESSONS_H5, QUESTIONS_H5, 9) + _validate("HR6", LESSONS_H6, QUESTIONS_H6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("HR 5", LESSONS_H5, QUESTIONS_H5, "performance",
         "Performance management in ZhiftERP: the Appraisal Template with weighted Key Result Areas totalling 100 and rating criteria; the Appraisal Cycle with appraisee-template mapping, the KRA evaluation method decision, and the published calendar; Goal records with KRA links, confirmation, and the freshness discipline; self appraisal and Employee Performance Feedback with independent submission and anchored scales; the final score computed from complete components and corrected only through its records; the completion, freshness, and calibration reads; and the boundary that appraisal informs pay decisions executed through the payroll lanes."),
        ("HR 6", LESSONS_H6, QUESTIONS_H6, "training",
         "Training in ZhiftERP: the Training Program register with compliance flags; the Training Event — type, trainer, the employee table built from due populations, the invitation flow, and the required-training statement; Training Results entered within the week with absentee and retake lanes; Training Feedback to its two readers; the annual plan from the three intakes with owner approval, quarterly execution, and cost reconciliation; the four standing reads; and compliance training — the register, the expiry arithmetic on passing results, the renewal window, the lapse procedure, and the joiner and mover rules."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.175.0"', '"3.176.0"'))
    print("  data: HR 5 + 6 lessons + banks REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.176.0")


if __name__ == "__main__":
    main()
